    EnsureMeosThreadInitialized();
    UnaryExecutor::Execute<string_t, uint32_t>(args.data[0], result, args.size(),
        [&](string_t in) {
            Pcpoint *v = BlobToPcpoint(in);
            uint32_t r = pcpoint_hash(v);
            free(v);
            return r;
        });
